// The font registry shared by the editor, the server renderer and the MCP tools.
//
// The catalogue (font-catalog.json) says which families Draft ships and which weights they should have.
// The metrics module (font-data.ts, generated by scripts/fonts.mjs from the font binaries) says which
// faces are actually on disk, with per-face advance widths and vertical metrics. Everything — text
// measurement, the editor's @font-face CSS and the agent-facing font list — reads from here, so what an
// agent lays out and what the browser paints use the same numbers.
import catalogJson from './font-catalog.json' with { type: 'json' };
import { FACES, RANGES, type FaceData } from './font-data.ts';

export type FontCategory = 'sans' | 'serif' | 'mono' | 'display';

interface CatalogFamily { name: string; slug: string; category: FontCategory; weights: number[]; italicWeights?: number[]; aliases?: string[] }

export type FontFace = FaceData;

export interface FontFamilyInfo {
  name: string;
  slug: string;
  category: FontCategory;
  weights: number[];
  italics: number[];
  aliases: string[];
}

const catalog = catalogJson as { families: CatalogFamily[] };

export { RANGES };
const RANGE_START: number[] = [];
const RANGE_TOTAL: number[] = [];
let total = 0;
for (const [from, to] of RANGES) { RANGE_START.push(total); RANGE_TOTAL.push(to - from + 1); total += to - from + 1; }

const WIDTHS = new Map<FontFace, Uint16Array>();

function decodeWidths(b64: string): Uint16Array {
  const bin = typeof atob === 'function'
    ? atob(b64)
    : (globalThis as unknown as { Buffer: { from(s: string, e: string): { toString(e: string): string } } }).Buffer.from(b64, 'base64').toString('binary');
  const out = new Uint16Array(bin.length / 2);
  for (let i = 0; i < out.length; i++) out[i] = (bin.charCodeAt(i * 2) & 0xff) | (bin.charCodeAt(i * 2 + 1) << 8);
  return out;
}

function widths(f: FontFace): Uint16Array {
  let w = WIDTHS.get(f);
  if (!w) { w = decodeWidths(f.w); WIDTHS.set(f, w); }
  return w;
}

/** Advance width of one code point in em units, or null when the face has no glyph for it. */
export function advance(f: FontFace, cp: number): number | null {
  for (let r = 0; r < RANGES.length; r++) {
    const [from, to] = RANGES[r];
    if (cp >= from && cp <= to) {
      const v = widths(f)[RANGE_START[r] + (cp - from)];
      return v ? v / f.upem : null;
    }
  }
  const sym = f.sym?.[cp];
  return sym ? sym / f.upem : null;
}

/** Average letter width in em units — the fallback for characters outside the stored ranges. */
export function averageWidth(f: FontFace): number { return f.avg / f.upem; }

const byKey = new Map<string, FontFace>();
for (const [key, f] of Object.entries(FACES)) byKey.set(key, f);

/** Families that actually have at least one face available. */
export const FAMILIES: FontFamilyInfo[] = catalog.families
  .map((c) => {
    const faces = Object.values(FACES).filter((f) => f.family === c.name);
    const weights = [...new Set(faces.map((f) => f.weight))].sort((a, b) => a - b);
    const italics = [...new Set(faces.filter((f) => f.italic).map((f) => f.weight))].sort((a, b) => a - b);
    return { name: c.name, slug: c.slug, category: c.category, weights, italics, aliases: c.aliases ?? [] };
  })
  .filter((f) => f.weights.length > 0);

const FAMILY_BY_NAME = new Map<string, FontFamilyInfo>();
for (const f of FAMILIES) {
  FAMILY_BY_NAME.set(f.name.toLowerCase(), f);
  for (const a of f.aliases) if (!FAMILY_BY_NAME.has(a.toLowerCase())) FAMILY_BY_NAME.set(a.toLowerCase(), f);
}

/** Font families the server always has a renderer-safe fallback for, besides the bundled catalogue. */
const SYSTEM_FAMILIES = new Set([
  'helvetica', 'helvetica neue', 'arial', 'georgia', 'times', 'times new roman', 'courier', 'courier new',
  'verdana', 'trebuchet ms', 'menlo', 'monaco', 'optima', 'palatino', 'avenir', 'avenir next', 'sf pro',
  'sf pro text', 'sf pro display', 'sf mono', 'system-ui', 'ui-sans-serif', 'ui-serif', 'ui-monospace', 'sans-serif', 'serif', 'monospace',
]);

/** Canonical family name for a user/agent string, or the trimmed original when it is not one of ours. */
export function normalizeFamily(name: string | undefined): string | undefined {
  if (name === undefined) return undefined;
  const raw = name.trim();
  if (!raw) return undefined;
  const hit = FAMILY_BY_NAME.get(raw.toLowerCase().replace(/\s+/g, ' '));
  return hit ? hit.name : raw;
}

export function familyInfo(name: string | undefined): FontFamilyInfo | undefined {
  if (!name) return undefined;
  return FAMILY_BY_NAME.get(name.trim().toLowerCase().replace(/\s+/g, ' '));
}

export function isKnownFamily(name: string | undefined): boolean {
  if (!name) return true;
  const raw = name.trim().toLowerCase().replace(/["']/g, '');
  if (FAMILY_BY_NAME.has(raw)) return true;
  // a CSS stack such as 'Helvetica Neue', Arial, sans-serif counts as known
  return raw.split(',').every((part) => SYSTEM_FAMILIES.has(part.trim()) || FAMILY_BY_NAME.has(part.trim()));
}

/**
 * CSS Fonts 4 §5.2.1 weight matching, so the face we measure with is the face Chrome and resvg
 * actually draw. Ties are not simply rounded up: below 400 the lighter side wins, and 400–500
 * prefers the lighter side before going heavier.
 */
export function matchWeight(weights: number[], want: number): number {
  const sorted = [...weights].sort((a, b) => a - b);
  if (!sorted.length) return want;
  if (want < 400) {
    const lighter = sorted.filter((w) => w <= want).reverse();
    return lighter[0] ?? sorted[0];
  }
  if (want <= 500) {
    const upTo500 = sorted.filter((w) => w >= want && w <= 500);
    if (upTo500.length) return upTo500[0];
    const lighter = sorted.filter((w) => w < want).reverse();
    if (lighter.length) return lighter[0];
    return sorted.filter((w) => w > 500)[0] ?? sorted[sorted.length - 1];
  }
  // above 500 the nearest heavier face wins before any lighter one
  const atOrAbove = sorted.filter((w) => w >= want);
  if (atOrAbove.length) return atOrAbove[0];
  return sorted.filter((w) => w < want).reverse()[0] ?? sorted[sorted.length - 1];
}

export function italicWeights(name: string | undefined): number[] {
  return familyInfo(name)?.italics ?? [];
}

/** The face a renderer will pick for this family/weight/style combination. */
export function faceFor(name: string | undefined, weight = 400, italic = false): FontFace | undefined {
  const fam = familyInfo(name);
  if (!fam) return undefined;
  if (italic && fam.italics.length) {
    return byKey.get(`${fam.name}/${matchWeight(fam.italics, weight)}/italic`);
  }
  return byKey.get(`${fam.name}/${matchWeight(fam.weights, weight)}/normal`);
}

/** Families every text run falls back through when the primary face has no glyph (⌘, Thai, symbols). */
export const FALLBACK_FAMILIES = ['Inter', 'Noto Sans', 'Geist'];

/**
 * CSS/SVG font-family for a run: the requested family, the bundled fallbacks, then a generic. The
 * measurement code walks the same list per character, so a ⌘ in Geist Mono is measured with — and drawn
 * by — Inter instead of being clipped.
 */
export function fontStack(name: string | undefined): string {
  const fam = familyInfo(name);
  if (!fam) return name ?? '';
  const generic = fam.category === 'mono' ? 'monospace' : fam.category === 'serif' ? 'serif' : 'sans-serif';
  const extra = FALLBACK_FAMILIES.filter((f) => f !== fam.name).map((f) => `"${f}"`);
  return [`"${fam.name}"`, ...extra, generic].join(', ');
}

/** Kept for callers that only want the family expression. */
export const cssFamily = fontStack;

/** Human/agent readable inventory, one line per family. */
export function fontInventory(): string {
  const order: FontCategory[] = ['sans', 'serif', 'mono', 'display'];
  const lines = ['Families available to fontFamily (weights in bold terms, italic where listed):'];
  for (const category of order) {
    const list = FAMILIES.filter((f) => f.category === category);
    if (!list.length) continue;
    lines.push(`${category}: ${list.map((f) => `${f.name} [${f.weights.join(', ')}${f.italics.length ? `; italic ${f.italics.join(', ')}` : ''}]`).join(' · ')}`);
  }
  lines.push('System fonts also work but render differently on other machines: Helvetica Neue, Helvetica, Arial, Georgia, Times New Roman, Verdana, Menlo, SF Pro.');
  return lines.join('\n');
}
